// Parse a CoStar-style CSV comp export into an array of raw comp row objects.
// Mirrors SOP.md Section 12, Step 2 and the canonical column set in Section 34.
const csvText = Buffer.from($input.first().binary.data.data, 'base64').toString('utf-8');
const opportunityId = $('Webhook - Comp File Upload').first().json.body.opportunity_id;

const lines = csvText.trim().split(/\r?\n/);
const headers = lines[0].split(',').map((h) => h.replace(/"/g, '').trim());

const expectedColumns = [
  'Property Address', 'City', 'State', 'Zip', 'Sale Date', 'Sale Price',
  'Building SF', 'Price/SF', 'Cap Rate', 'NOI', 'Building Class', 'Occupancy %'
];
const missing = expectedColumns.filter((c) => !headers.includes(c));
if (missing.length > 0) {
  throw new Error(`CoStar template drift detected. Missing columns: ${missing.join(', ')}`);
}

const rows = lines.slice(1).filter((l) => l.trim().length > 0).map((line) => {
  const cells = line.split(',').map((c) => c.replace(/"/g, '').trim());
  const row = {};
  headers.forEach((h, i) => { row[h] = cells[i]; });
  return {
    address: row['Property Address'],
    city: row['City'],
    state: row['State'],
    zip: row['Zip'],
    sale_date: row['Sale Date'],
    sale_price_usd: Number(row['Sale Price'].replace(/[$,]/g, '')),
    building_sf: Number(row['Building SF']),
    price_per_sf: Number(row['Price/SF'].replace(/[$,]/g, '')),
    cap_rate: Number(row['Cap Rate'].replace('%', '')) / 100,
    noi_annual_usd: Number(row['NOI'].replace(/[$,]/g, '')),
    building_class: row['Building Class'],
    occupancy_pct: Number(row['Occupancy %'].replace('%', '')) / 100,
    source_platform: 'CoStar',
    opportunity_id: opportunityId
  };
});

return rows.map((r) => ({ json: r }));

// Extract raw text layer from an uploaded LoopNet PDF (placeholder for a
// real pdf-parse / textract call). SOP.md Section 12, Step 3.
const pdfBinary = $input.first().binary.data.data;
const opportunityId = $('Webhook - Comp File Upload').first().json.body.opportunity_id;

// In production this delegates to a PDF text-extraction library or an
// OCR fallback when the text layer is sparse (SOP.md Section 17, Scenario 1).
const extractedText = $input.first().json.extractedText || '[PDF TEXT EXTRACTION PLACEHOLDER]';

return [{
  json: {
    opportunity_id: opportunityId,
    raw_pdf_text: extractedText,
    source_platform: 'LoopNet'
  }
}];

// Normalize both the CSV path and the Claude-extracted PDF path into the
// single canonical comp schema (SOP.md Section 34, Appendix).
const items = $input.all();
const normalized = items.map((item) => {
  const j = item.json;
  // If this item came through the Claude extraction branch, unwrap its response.
  if (j.content && Array.isArray(j.content)) {
    const parsed = JSON.parse(j.content[0].text);
    return {
      json: {
        comp_id: `cmp_${Buffer.from(parsed.address + parsed.transaction_date).toString('hex').slice(0, 12)}`,
        source_platform: 'LoopNet',
        address: parsed.address,
        transaction_type: parsed.transaction_type,
        transaction_date: parsed.transaction_date,
        price_per_sf: parsed.price_per_sf,
        cap_rate: parsed.cap_rate,
        noi_annual_usd: parsed.noi_annual,
        building_class: parsed.building_class,
        tenant_vacancy_notes: parsed.tenant_vacancy_notes,
        needs_review: Object.values(parsed.confidence || {}).includes('low')
      }
    };
  }
  // CSV path: already close to canonical shape.
  return {
    json: {
      comp_id: `cmp_${Buffer.from(j.address + j.sale_date).toString('hex').slice(0, 12)}`,
      source_platform: j.source_platform,
      address: j.address,
      transaction_type: 'sale',
      transaction_date: j.sale_date,
      price_per_sf: j.price_per_sf,
      cap_rate: j.cap_rate,
      noi_annual_usd: j.noi_annual_usd,
      building_class: j.building_class,
      tenant_vacancy_notes: null,
      needs_review: false,
      opportunity_id: j.opportunity_id
    }
  };
});
return normalized;

// Statistical outlier detection: 2-standard-deviation rule against the
// comp set's median cap rate (SOP.md Section 14).
const MIN_COMPS_FOR_STATISTICS = 5;
const OUTLIER_THRESHOLD_STD_DEV = 2.0;

const comps = $input.all().map((i) => i.json);

function median(values) {
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function stdev(values) {
  const m = values.reduce((a, b) => a + b, 0) / values.length;
  const variance = values.reduce((sum, v) => sum + Math.pow(v - m, 2), 0) / (values.length - 1);
  return Math.sqrt(variance);
}

if (comps.length < MIN_COMPS_FOR_STATISTICS) {
  return comps.map((c) => ({ json: { ...c, is_outlier: false, needs_review: true, accepted: false } }));
}

const capRates = comps.map((c) => c.cap_rate);
const medianCapRate = median(capRates);
const capRateStdev = stdev(capRates);

return comps.map((c) => {
  const deviation = Math.abs(c.cap_rate - medianCapRate);
  const isOutlier = capRateStdev > 0 && deviation > OUTLIER_THRESHOLD_STD_DEV * capRateStdev;
  return {
    json: {
      ...c,
      is_outlier: isOutlier,
      accepted: !isOutlier,
      median_cap_rate: medianCapRate,
      cap_rate_stdev: capRateStdev
    }
  };
});

